CREATE TABLE IF NOT EXISTS public.seo_control_registry(
 control_id text PRIMARY KEY, family text NOT NULL, variable_name text NOT NULL,
 control_level text NOT NULL CHECK(control_level IN('direct','partial')),
 observation_status text NOT NULL CHECK(observation_status IN('automated','partial','not_instrumented','approval_required')),
 evidence_source text NOT NULL, execution_policy text NOT NULL,
 review_cadence text NOT NULL CHECK(review_cadence IN('daily','weekly','monthly')),
 last_verified_at timestamptz,
 last_observation jsonb NOT NULL DEFAULT '{}'::jsonb,
 updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.seo_control_registry ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.seo_control_registry FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE ON public.seo_control_registry TO service_role;

INSERT INTO public.seo_control_registry(control_id,family,variable_name,control_level,observation_status,evidence_source,execution_policy,review_cadence)
SELECT x.control_id,x.family,x.variable_name,x.control_level,x.observation_status,x.evidence_source,x.execution_policy,x.review_cadence
FROM jsonb_to_recordset('[{"control_id":"accessibility","family":"Experiencia","variable_name":"Accessibility and semantic structure","control_level":"direct","observation_status":"partial","evidence_source":"Browser checks and semantic markup","execution_policy":"Fix high-confidence issues without changing visual styles","review_cadence":"monthly"},{"control_id":"avg_positions","family":"Busquedas","variable_name":"Organic positions by query URL","control_level":"partial","observation_status":"automated","evidence_source":"search_console_daily","execution_policy":"Measure trend 28/56 days, no causal claims","review_cadence":"weekly"},{"control_id":"backlink_monitor","family":"Autoridad","variable_name":"Referring domains and backlinks","control_level":"partial","observation_status":"not_instrumented","evidence_source":"No complete source confirmed","execution_policy":"Use free legitimate public sources; flag gaps","review_cadence":"monthly"},{"control_id":"brand_authority","family":"Autoridad","variable_name":"Brand mentions and credible sources","control_level":"partial","observation_status":"partial","evidence_source":"Public business links and content","execution_policy":"No artificial link building or paid outreach","review_cadence":"monthly"},{"control_id":"broken_links","family":"Tecnico","variable_name":"Broken links and redirects","control_level":"direct","observation_status":"automated","evidence_source":"seo-internal-links.py","execution_policy":"Repair validated broken internal destinations","review_cadence":"weekly"},{"control_id":"cannibalization","family":"Arquitectura","variable_name":"Topic overlap and canibalization","control_level":"partial","observation_status":"partial","evidence_source":"GSC by query and URL","execution_policy":"Consolidate editorial focus, no URL changes without permission","review_cadence":"monthly"},{"control_id":"canonical_hreflang","family":"Tecnico","variable_name":"Canonical and localized hreflang","control_level":"direct","observation_status":"automated","evidence_source":"seo-weekly-health scripts","execution_policy":"Propose tested metadata fixes","review_cadence":"weekly"},{"control_id":"content_evidence","family":"Contenido","variable_name":"Content accuracy and commercial proof","control_level":"direct","observation_status":"partial","evidence_source":"Article sources, portfolio, editorial audit","execution_policy":"No unverified client claims","review_cadence":"weekly"},{"control_id":"content_freshness","family":"Contenido","variable_name":"Outdated content corrections","control_level":"direct","observation_status":"partial","evidence_source":"Source review and weekly strategy","execution_policy":"Update only when source evidence permits","review_cadence":"monthly"},{"control_id":"core_web_vitals","family":"Experiencia","variable_name":"LCP INP CLS in field","control_level":"partial","observation_status":"not_instrumented","evidence_source":"No verified longitudinal CrUX source","execution_policy":"Add free CrUX/PSI measurement when source available","review_cadence":"monthly"},{"control_id":"crawlability","family":"Tecnico","variable_name":"Crawling and HTTP status","control_level":"direct","observation_status":"automated","evidence_source":"GitHub seo-weekly-health","execution_policy":"Repair crawl failures after tests","review_cadence":"weekly"},{"control_id":"cta_forms","family":"Conversion","variable_name":"Calls to action and forms","control_level":"direct","observation_status":"partial","evidence_source":"CRM, website forms, visual gate","execution_policy":"Improve wording without changing commercial promises","review_cadence":"weekly"},{"control_id":"ctr_snippets","family":"Busquedas","variable_name":"Title snippet and organic CTR","control_level":"partial","observation_status":"automated","evidence_source":"GSC query/page/CTR","execution_policy":"Test page copy and snippets with proper baselines","review_cadence":"weekly"},{"control_id":"experiment_log","family":"Aprendizaje","variable_name":"SEO change impact and rollback","control_level":"direct","observation_status":"partial","evidence_source":"seo_editorial_drafts, seo_knowledge_revisions","execution_policy":"Record baseline and compare 28/56 days","review_cadence":"weekly"},{"control_id":"ga4_events","family":"Conversion","variable_name":"GA4 event coverage","control_level":"direct","observation_status":"automated","evidence_source":"metrics-daily sync and GA4","execution_policy":"Check measurement consistency","review_cadence":"daily"},{"control_id":"indexation","family":"Tecnico","variable_name":"Google URL indexation","control_level":"partial","observation_status":"partial","evidence_source":"Google URL Inspection, 5 daily","execution_policy":"Correct eligible issues, never claim instant indexing","review_cadence":"daily"},{"control_id":"internal_linking","family":"Arquitectura","variable_name":"Contextual internal links","control_level":"direct","observation_status":"partial","evidence_source":"seo_pages.internal_links and audit","execution_policy":"Only existing destinations and visually verified anchors","review_cadence":"weekly"},{"control_id":"keyword_coverage","family":"Busquedas","variable_name":"Observed commercial search query coverage","control_level":"direct","observation_status":"automated","evidence_source":"search_console_daily, seo_keyword_targets","execution_policy":"Grow relevant queries naturally, not keyword stuffing","review_cadence":"weekly"},{"control_id":"lead_attribution","family":"Conversion","variable_name":"Organic qualified lead attribution","control_level":"direct","observation_status":"partial","evidence_source":"GA4/website_inquiries/CRM","execution_policy":"Distinguish click from submitted and qualified lead","review_cadence":"weekly"},{"control_id":"locales","family":"Contenido","variable_name":"Spanish/Catalan/English consistency","control_level":"direct","observation_status":"partial","evidence_source":"locale content and hreflang","execution_policy":"Keep original language and visual identity","review_cadence":"weekly"},{"control_id":"orphan_pages","family":"Arquitectura","variable_name":"Orphan page discovery","control_level":"direct","observation_status":"partial","evidence_source":"sitemap and link audit","execution_policy":"Connect valuable isolated pages","review_cadence":"monthly"},{"control_id":"page_semantics","family":"Contenido","variable_name":"Headline and visible copy relevance","control_level":"direct","observation_status":"automated","evidence_source":"seo_editorial_drafts and knowledge drafts","execution_policy":"Evidence-backed textual edits behind visual gate","review_cadence":"weekly"},{"control_id":"responsive_visual","family":"Experiencia","variable_name":"Responsive layout and design stability","control_level":"direct","observation_status":"partial","evidence_source":"Playwright gate for services and Knowledge","execution_policy":"Never publish failing mobile/tablet/desktop QA","review_cadence":"weekly"},{"control_id":"robots_sitemap","family":"Tecnico","variable_name":"robots.txt and sitemap.xml","control_level":"direct","observation_status":"automated","evidence_source":"seo-weekly-health scripts","execution_policy":"Validate technical fixes before publish","review_cadence":"weekly"},{"control_id":"serp_competitors","family":"Competencia","variable_name":"Competitor SERP and intent research","control_level":"partial","observation_status":"partial","evidence_source":"Weekly contextual web research","execution_policy":"Verify SERP per market rather than invent rankings","review_cadence":"weekly"},{"control_id":"structured_data","family":"Tecnico","variable_name":"Structured data validity","control_level":"direct","observation_status":"partial","evidence_source":"SEO production audit","execution_policy":"Test schemas, no fabricated rich results","review_cadence":"weekly"},{"control_id":"technical_performance","family":"Experiencia","variable_name":"Network and build performance","control_level":"direct","observation_status":"partial","evidence_source":"Vercel and Next.js build logs","execution_policy":"Correct proven regressions within free limits","review_cadence":"weekly"}]'::jsonb) AS x(control_id text,family text,variable_name text,control_level text,observation_status text,evidence_source text,execution_policy text,review_cadence text)
ON CONFLICT (control_id) DO NOTHING;
